  description: DEFAULT_DESCRIPTION,
  input: z.object({
    id: z
      .union([z.string(), z.number()])
      .describe('The ID of the document to duplicate from'),
    data: z
      .record(z.string(), z.unknown())
      .describe('Optional: fields to override on the duplicated document')
      .optional(),
    depth: z
      .number()
      .int()
      .min(0)
      .max(10)
      .describe('How many levels deep to populate relationships in response')
      .optional()
      .default(0),
    draft: z
      .boolean()
      .describe('Whether to create the duplicate as a draft')
      .optional(),
    fallbackLocale: z
      .string()
      .describe('Optional: fallback locale code to use when requested locale is not available')
      .optional(),
    locale: z
      .string()
      .describe('Optional: locale code to duplicate the document in (e.g., "en", "es")')
      .optional(),
    select: z
      .record(z.string(), z.unknown())
      .describe(
        'Optional: define exactly which fields you\'d like to return, e.g., {"title": true}',
      )
      .optional(),
  }),
}).handler(async ({ authorizedMCP, collectionSlug, input, req }) => {
  const payload = req.payload
  const logger = getLogger({ payload })

  const { id, data, depth, draft, fallbackLocale, locale, select } = input

  logger.info(
    `Duplicating document ${id} in collection: ${collectionSlug}${locale ? ` with locale: ${locale}` : ''}`,
  )

  try {
    let overrideData: Record<string, unknown> | undefined
    if (data) {
      const virtualFieldNames = getCollectionVirtualFieldNames(payload.config, collectionSlug)
      overrideData = transformPointDataToPayload(stripVirtualFields(data, virtualFieldNames))
    }

    const result = await payload.duplicate({
      id,
      collection: collectionSlug,
      depth,
      req,
      ...localAPIDefaults(authorizedMCP),
      ...(overrideData && { data: overrideData }),
      ...(draft !== undefined && { draft }),
      ...(locale && { locale }),
      ...(fallbackLocale && { fallbackLocale }),
      ...(select && { select: select as SelectType }),
    })

    logger.info(
      `Successfully duplicated document ${id} in ${collectionSlug} as ${(result as { id: unknown }).id}`,
    )

    return {
      content: [
